            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control @ValidationCss(Company)" value="@Company"
                       @onchange="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Company))
                {
                    <div class="invalid-feedback d-block">Company name is required.</div>
                }
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control @ValidationCss(Title)" value="@Title"
                       @onchange="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Title))
                {
                    <div class="invalid-feedback d-block">Job title is required.</div>
                }
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control @(ShowValidation && StartDate == default ? "is-invalid" : "")"
                       value="@(StartDate == default ? "" : StartDate.ToString("yyyy-MM-dd"))"
                       @onchange="e => { if (DateTime.TryParse(e.Value?.ToString(), out var d)) StartDate = d; NotifyChanged(); }" />
                @if (ShowValidation && StartDate == default)
                {
                    <div class="invalid-feedback d-block">Start date is required.</div>
                }
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" disabled="@IsCurrent"
                       value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       @onchange="e => { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="current-@EntryNumber" checked="@IsCurrent"
                           @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                    <label class="form-check-label" for="current-@EntryNumber">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int EntryNumber { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public bool ShowValidation { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public WorkEntryData? InitialData { get; set; }

    private string Company { get; set; } = "";
    private string Title { get; set; } = "";
    private DateTime StartDate { get; set; }
    private DateTime? EndDate { get; set; }
    private bool IsCurrent { get; set; }
    private string Description { get; set; } = "";

    protected override void OnParametersSet()
    {
        if (InitialData is not null)
        {
            Company = InitialData.Company;
            Title = InitialData.Title;
            StartDate = InitialData.StartDate;
            EndDate = InitialData.EndDate;
            IsCurrent = InitialData.IsCurrent;
            Description = InitialData.Description;
        }
    }

    private string ValidationCss(string value) =>
        ShowValidation && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private async Task NotifyChanged()
    {
        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task OnRemoveClicked() => await OnRemove.InvokeAsync();

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}
