@using sv_12d51d80404140aaa6a1d66d7c80b001.Models

<h4 class="mb-3">Personal Information</h4>

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationCss(FullName)" @bind="FullName" />
        @if (_showValidation && string.IsNullOrWhiteSpace(FullName))
        {
            <div class="invalid-feedback d-block">Full name is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @EmailValidationCss()" @bind="Email" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Email))
        {
            <div class="invalid-feedback d-block">Email is required.</div>
        }
        else if (_emailError is not null)
        {
            <div class="invalid-feedback d-block">@_emailError</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @ValidationCss(Phone)" @bind="Phone" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Phone))
        {
            <div class="invalid-feedback d-block">Phone number is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationCss(Address)" @bind="Address" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Address))
        {
            <div class="invalid-feedback d-block">Address is required.</div>
        }
    </div>
</div>

@if (_validating)
{
    <div class="mt-3 text-muted"><span class="spinner-border spinner-border-sm me-1"></span> Validating email…</div>
}

<div class="mt-4 d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">Next →</button>
</div>

@code {
    [Parameter] public PersonalInfo? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    private bool _showValidation;
    private bool _validating;
    private string? _emailError;

    protected override void OnParametersSet()
    {
        if (Model is not null)
        {
            FullName = Model.FullName;
            Email = Model.Email;
            Phone = Model.Phone;
            Address = Model.Address;
        }
    }

    private string ValidationCss(string value) =>
        _showValidation && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private string EmailValidationCss() =>
        (_showValidation && string.IsNullOrWhiteSpace(Email)) || _emailError is not null ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _showValidation = true;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
            return;

        _validating = true;
        try
        {
            var isValid = await ValidateEmail(Email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            _validating = false;
        }
    }
}

@using sv_12d51d80404140aaa6a1d66d7c80b001.Models
@using static sv_12d51d80404140aaa6a1d66d7c80b001.Components.Pages.Apply.WorkEntryEditor

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < _entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor EntryNumber="@(index + 1)"
                     ShowRemove="@(_entries.Count > 1)"
                     ShowValidation="@_showValidation"
                     InitialData="@_entries[index]"
                     OnChanged="data => UpdateEntry(index, data)"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="HandleBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public WorkHistory? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntryData> _entries = new();
    private bool _showValidation;

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Entries.Count > 0 && _entries.Count == 0)
        {
            _entries = Model.Entries.Select(e => new WorkEntryData(
                e.Company, e.Title, e.StartDate, e.EndDate, e.EndDate is null, e.Description
            )).ToList();
        }

        if (_entries.Count == 0)
            _entries.Add(new WorkEntryData("", "", default, null, false, ""));
    }

    private void AddEntry() =>
        _entries.Add(new WorkEntryData("", "", default, null, false, ""));

    private void RemoveEntry(int index)
    {
        if (_entries.Count > 1)
            _entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryData data)
    {
        if (index < _entries.Count)
            _entries[index] = data;
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();

    private async Task HandleNext()
    {
        _showValidation = true;

        var allValid = _entries.All(e =>
            !string.IsNullOrWhiteSpace(e.Company) &&
            !string.IsNullOrWhiteSpace(e.Title) &&
            e.StartDate != default);

        if (!allValid)
            return;

        var workEntries = _entries.Select(e =>
            new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description.Trim())
        ).ToList();

        await OnNext.InvokeAsync(new WorkHistory(workEntries));
    }
}

@using sv_12d51d80404140aaa6a1d66d7c80b001.Models
@using static sv_12d51d80404140aaa6a1d66d7c80b001.Components.Pages.Apply.ReferenceEditor

<h4 class="mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < _references.Count; i++)
{
    var index = i;
    <ReferenceEditor ReferenceNumber="@(index + 1)"
                     ShowRemove="@(_references.Count > 1)"
                     ShowValidation="@_showValidation"
                     InitialData="@_references[index]"
                     OnChanged="data => UpdateReference(index, data)"
                     OnRemove="() => RemoveReference(index)" />
}

@if (_references.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="HandleBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public List<Reference>? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceData> _references = new();
    private bool _showValidation;

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Count > 0 && _references.Count == 0)
        {
            _references = Model.Select(r => new ReferenceData(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        }

        if (_references.Count == 0)
        {
            _references.Add(new ReferenceData("", "", "", ""));
            _references.Add(new ReferenceData("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceData("", "", "", ""));
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceData data)
    {
        if (index < _references.Count)
            _references[index] = data;
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();

    private async Task HandleNext()
    {
        _showValidation = true;

        var allValid = _references.All(r =>
            !string.IsNullOrWhiteSpace(r.Name) &&
            !string.IsNullOrWhiteSpace(r.Relationship) &&
            !string.IsNullOrWhiteSpace(r.Email) &&
            !string.IsNullOrWhiteSpace(r.Phone));

        if (!allValid)
            return;

        var refs = _references.Select(r =>
            new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())
        ).ToList();

        await OnNext.InvokeAsync(refs);
    }
}

