        {
            <div class="invalid-feedback d-block">Email is required.</div>
        }
        else if (_emailError is not null)
        {
            <div class="invalid-feedback d-block">@_emailError</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @ValidationCss(Phone)" @bind="Phone" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Phone))
        {
            <div class="invalid-feedback d-block">Phone number is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationCss(Address)" @bind="Address" />
        @if (_showValidation && string.IsNullOrWhiteSpace(Address))
        {
            <div class="invalid-feedback d-block">Address is required.</div>
        }
    </div>
