@code {
    [Parameter] public PersonalInfo? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    private bool _showValidation;
    private bool _validating;
    private string? _emailError;

    protected override void OnParametersSet()
    {
        if (Model is not null)
        {
            FullName = Model.FullName;
            Email = Model.Email;
            Phone = Model.Phone;
            Address = Model.Address;
        }
    }

    private string ValidationCss(string value) =>
        _showValidation && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private string EmailValidationCss() =>
        (_showValidation && string.IsNullOrWhiteSpace(Email)) || _emailError is not null ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _showValidation = true;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
            return;

        _validating = true;
        try
        {
            var isValid = await ValidateEmail(Email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            _validating = false;
        }
    }
}

