@using sv_12d51d80404140aaa6a1d66d7c80b001.Models
@using static sv_12d51d80404140aaa6a1d66d7c80b001.Components.Pages.Apply.ReferenceEditor

<h4 class="mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < _references.Count; i++)
{
    var index = i;
    <ReferenceEditor ReferenceNumber="@(index + 1)"
                     ShowRemove="@(_references.Count > 1)"
                     ShowValidation="@_showValidation"
                     InitialData="@_references[index]"
                     OnChanged="data => UpdateReference(index, data)"
                     OnRemove="() => RemoveReference(index)" />
}

@if (_references.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="HandleBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter] public List<Reference>? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceData> _references = new();
    private bool _showValidation;

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Count > 0 && _references.Count == 0)
        {
            _references = Model.Select(r => new ReferenceData(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        }

        if (_references.Count == 0)
        {
            _references.Add(new ReferenceData("", "", "", ""));
            _references.Add(new ReferenceData("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceData("", "", "", ""));
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceData data)
    {
        if (index < _references.Count)
            _references[index] = data;
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();

    private async Task HandleNext()
    {
        _showValidation = true;

        var allValid = _references.All(r =>
            !string.IsNullOrWhiteSpace(r.Name) &&
            !string.IsNullOrWhiteSpace(r.Relationship) &&
            !string.IsNullOrWhiteSpace(r.Email) &&
            !string.IsNullOrWhiteSpace(r.Phone));

        if (!allValid)
            return;

        var refs = _references.Select(r =>
            new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())
        ).ToList();

        await OnNext.InvokeAsync(refs);
    }
}

