@using sv_12d51d80404140aaa6a1d66d7c80b001.Models

<h4 class="mb-3">Review Your Application</h4>

@* Personal Info *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <a href="#" @onclick="() => EditStep(0)" @onclick:preventDefault class="text-primary">Edit</a>
    </div>
    <div class="card-body">
        @if (Personal is not null)
        {
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
            </dl>
        }
    </div>
</div>

@* Work History *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <a href="#" @onclick="() => EditStep(1)" @onclick:preventDefault class="text-primary">Edit</a>
    </div>
    <div class="card-body">
        @if (Work is not null)
        {
            @foreach (var entry in Work.Entries)
            {
                <div class="mb-3">
                    <h6 class="mb-1">@entry.Title at @entry.Company</h6>
                    <small class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        }
    </div>
</div>

@* References *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <a href="#" @onclick="() => EditStep(2)" @onclick:preventDefault class="text-primary">Edit</a>
    </div>
    <div class="card-body">
        @if (References is not null)
        {
            @foreach (var r in References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> — @r.Relationship<br />
                    <small class="text-muted">@r.Email · @r.Phone</small>
                </div>
            }
        }
    </div>
</div>

@* Cover Letter *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <a href="#" @onclick="() => EditStep(3)" @onclick:preventDefault class="text-primary">Edit</a>
    </div>
    <div class="card-body">
        <p style="white-space: pre-wrap;">@CoverLetter</p>
    </div>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger">@_errorMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="HandleBack">← Back</button>
    <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_submitting">
        @if (_submitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Submit Application
    </button>
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEdit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    private bool _submitting;
    private string? _errorMessage;

    private async Task EditStep(int step) => await OnEdit.InvokeAsync(step);

    private async Task HandleBack() => await OnBack.InvokeAsync();

    private async Task HandleSubmit()
    {
        _submitting = true;
        _errorMessage = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }
