@page "/apply"
@using sv_12d51d80404140aaa6a1d66d7c80b001.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="text-center py-5">
            <div class="mb-3">
                <span class="display-1 text-success">✓</span>
            </div>
            <h3>Application Submitted!</h3>
            <p class="lead text-muted">Your application ID is <strong>#@_applicationId</strong></p>
            <p>We'll review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@_currentStep"
                       CompletedSteps="@_completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Model="@_personalInfo"
                                  ValidateEmail="ValidateEmailAsync"
                                  OnNext="OnPersonalInfoNext" />
                break;
            case 1:
                <WorkHistoryStep Model="@_workHistory"
                                 OnNext="OnWorkHistoryNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep Model="@_references"
                                OnNext="OnReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep Model="@_coverLetter"
                                 OnNext="OnCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="@_personalInfo"
                            Work="@_workHistory"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            OnEdit="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication" />
                break;
        }
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();
    private bool _submitted;
    private int _applicationId;

    // Form state
    private PersonalInfo? _personalInfo;
    private WorkHistory? _workHistory;
    private List<Reference>? _references;
    private string? _coverLetter;

    private async Task<bool> ValidateEmailAsync(string email) =>
        await ApplicationService.ValidateEmailAsync(email);

    private void OnPersonalInfoNext(PersonalInfo info)
    {
        _personalInfo = info;
        CompleteAndAdvance(0);
    }

    private void OnWorkHistoryNext(WorkHistory work)
    {
        _workHistory = work;
        CompleteAndAdvance(1);
    }

    private void OnReferencesNext(List<Reference> refs)
    {
        _references = refs;
        CompleteAndAdvance(2);
    }

    private void OnCoverLetterNext(string letter)
    {
        _coverLetter = letter;
        CompleteAndAdvance(3);
    }

    private void CompleteAndAdvance(int step)
    {
        _completedSteps.Add(step);
        _currentStep = step + 1;
    }

    private void GoToStep(int step) => _currentStep = step;

    private void GoBack() => _currentStep = Math.Max(0, _currentStep - 1);

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personalInfo!,
            _workHistory!,
            _references!,
            _coverLetter!
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

