                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemoveClicked">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control @ValidationCss(Name)"
                       @bind="Name" @bind:after="NotifyChanged" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Name))
                {
                    <div class="invalid-feedback d-block">Name is required.</div>
                }
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input type="text" class="form-control @ValidationCss(Relationship)"
                       @bind="Relationship" @bind:after="NotifyChanged" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Relationship))
                {
                    <div class="invalid-feedback d-block">Relationship is required.</div>
                }
            </div>
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control @ValidationCss(Email)"
                       @bind="Email" @bind:after="NotifyChanged" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Email))
                {
                    <div class="invalid-feedback d-block">Email is required.</div>
                }
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control @ValidationCss(Phone)"
                       @bind="Phone" @bind:after="NotifyChanged" />
                @if (ShowValidation && string.IsNullOrWhiteSpace(Phone))
                {
                    <div class="invalid-feedback d-block">Phone is required.</div>
                }
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int ReferenceNumber { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public bool ShowValidation { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }
    [Parameter] public ReferenceData? InitialData { get; set; }

    private string Name { get; set; } = string.Empty;
    private string Relationship { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;

    protected override void OnParametersSet()
    {
        if (InitialData is not null)
        {
            Name = InitialData.Name;
            Relationship = InitialData.Relationship;
            Email = InitialData.Email;
            Phone = InitialData.Phone;
        }
    }

    private string ValidationCss(string value) =>
        ShowValidation && string.IsNullOrWhiteSpace(value) ? "is-invalid" : string.Empty;

    private async Task NotifyChanged()
    {
        await OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    private async Task OnRemoveClicked() => await OnRemove.InvokeAsync();

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}"}

